        # hand-crafted chain; compare on the sealed (lower) version
        # semantics by re-serializing the later record's evidence is
        # impossible without a directory. This cannot occur for
        # chains this class writes.
        raise ValueError(
            "recovery chain frames embed records of different "
            "versions"
